hand builder build "#639"; sleep 1; hand builder build "#700"
dec builder; echo "builder: $(dj) / log: $(last)"; eq "$(dj)" "T=1 admit:b#700:- held:b#639"; eq "$(last)" "admit:b#700:c7:-"
$C schedule summary $P | tee /dev/stderr | grep -q "queued build 1; deferred 0; held 1 #639;" || exit 1
for i in 1 2 3; do dec builder; eq "$(dj)" "T=1 admit:b#700:reserved held:b#639"; done
for i in $(ids builder-lead | tail -1); do echo "done: $i" >> $S/status/builder-lead.status; done; $C schedule release --pool builder "#700" $P >/dev/null
dec builder; echo "slot free, only #639 left: $(dj) / log: '$(last)'"; eq "$(dj)" "T=1 held:b#639"; eq "$(last)" ""; eq "$(res)" ""
seed 1 200 0; dec builder low; echo "interval due, signals low, only held demand: $(dj)"; eq "$(tgt)" "1"; eq "$(dj)" "T=1 held:b#639"
$C schedule summary $P | tee /dev/stderr | grep -q "queued none; deferred 0; held 1 #639;" || exit 1

