out=$($C lead handoff builder build "#639" --wait-ack 5 $P) || exit 1; echo "$out"
new=$(python3 -c "import json,sys; print([m['id'] for m in map(json.loads, open(sys.argv[1])) if m['refs'] == ['#639']][-1])" $S/inbox/builder-lead.jsonl)
test "$new" != "$old" && echo "$out" | grep -qx "crew: sent $new to builder-lead" && ! echo "$out" | grep -q "$old" || exit 1
seed 1 0 0; dec builder; echo "fresh handoff $new: $(dj)"; eq "$(dj)" "T=1 admit:b#639:-"
